ValidationRule.errorConditionFormula:
if(ISCHANGED(Markfordeletion__c), 

PRIORVALUE(Markfordeletion__c) ,


(Markfordeletion__c &&
NOT(ISNEW()) 

)

)

&&
NOT(
($Profile.Name = 'Integration Profile' ||
$Profile.Name = 'System Administrator' ||
$Profile.Name = 'PaymentUrl Profile' ||
$Profile.Name = 'Finance Team'
)
)
